import net.neoforged.neoforge.common.data.DataMapProvider;
import net.neoforged.neoforge.common.data.DatapackBuiltinEntriesProvider;
import net.minecraft.core.RegistrySetBuilder;
import net.minecraft.data.worldgen.BootstrapContext;

// In GatherDataEvent
RegistrySetBuilder builder = new RegistrySetBuilder();
builder.add(Registries.Keys.CONFIGURED_FEATURE, bootstrap -> {
    // Register configured features
    bootstrap.register(MY_FEATURE, ConfiguredFeature.feature(myFeature));
});

provider.addProvider(event.getGenerator(), output -> 
    new DataMapProvider(output, builder));
